<?php
require_once __DIR__.'/config/config.php';
$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT c.*,u.name teacher_name FROM courses c LEFT JOIN users u ON u.id=c.teacher_id WHERE c.id=? AND c.is_published=1");$s->execute([$id]);$course=$s->fetch();if(!$course){http_response_code(404);exit('Course not found');}
$user=current_user();$enrolled=false;if($user){$q=db()->prepare("SELECT id FROM enrollments WHERE user_id=? AND course_id=?");$q->execute([$user['id'],$id]);$enrolled=(bool)$q->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){require_login();verify_csrf();$s=db()->prepare("INSERT IGNORE INTO enrollments(user_id,course_id) VALUES(?,?)");$s->execute([$user['id'],$id]);flash('You are enrolled. Enjoy learning!');redirect('/course.php?id='.$id);}
$q=db()->prepare("SELECT l.*,(SELECT COUNT(*) FROM quizzes q WHERE q.lesson_id=l.id) quiz_count FROM lessons l WHERE l.course_id=? AND l.is_published=1 ORDER BY lesson_order");$q->execute([$id]);$lessons=$q->fetchAll();$page_title=$course['title'].' — LinguaFree';include __DIR__.'/includes/header.php'; ?>
<div class="page-head"><div><span class="eyebrow"><?= e($course['flag_emoji']) ?> <?= e($course['language_name']) ?> · <?= e($course['level']) ?></span><h1><?= e($course['title']) ?></h1><p><?= e($course['description']) ?></p></div><?php if(!$user): ?><a class="btn btn-primary" href="<?= BASE_URL ?>/login.php">Log in to enroll</a><?php elseif(!$enrolled): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><button class="btn btn-primary">Enroll for free →</button></form><?php else: ?><span class="free-pill">✓ ENROLLED</span><?php endif; ?></div>
<h2 class="subheading">Course lessons</h2><?php if(!$lessons): ?><div class="empty">Lessons are being prepared by our teachers. Please check back soon.</div><?php endif; ?>
<div class="lesson-list"><?php foreach($lessons as $l): ?><article><div><span class="lesson-number"><?= (int)$l['lesson_order'] ?></span><b><?= e($l['title']) ?></b><small><?= (int)$l['duration_minutes'] ?> min · <?= (int)$l['quiz_count'] ?> quiz questions</small></div><?php if($enrolled): ?><a class="btn btn-outline" href="<?= BASE_URL ?>/lesson.php?id=<?= (int)$l['id'] ?>">Open lesson →</a><?php else: ?><span class="muted">Enroll to access</span><?php endif; ?></article><?php endforeach; ?></div>
<?php include __DIR__.'/includes/footer.php'; ?>